function runScript(
  scriptPath,
  timeoutMs,
  {
    preloads = [],
    scriptArguments = [],
    environment,
    cwd = repositoryRoot,
  },
) {
  return new Promise((resolve) => {
    const started = performance.now();
    const absoluteScript = path.isAbsolute(scriptPath)
      ? scriptPath
      : path.resolve(repositoryRoot, scriptPath);
    const argv = [
      ...preloads.flatMap((preload) => ["--import", preload]),
      absoluteScript,
      ...scriptArguments,
    ];
    const child = spawn(process.execPath, argv, {
      cwd,
      env: environment,
      shell: false,
      stdio: ["ignore", "pipe", "pipe"],
    });
    let stdout = Buffer.alloc(0);
    let stderr = Buffer.alloc(0);
    let overflow = false;
    let timedOut = false;
    let settled = false;
    const finish = (result) => {
      if (settled) return;
      settled = true;
      resolve({
        ...result,
        durationMs: Math.round(performance.now() - started),
        stdout: stdout.toString("utf8"),
        stderr: stderr.toString("utf8"),
        overflow,
        timedOut,
      });
    };
    const append = (current, chunk) => {
      const next = Buffer.concat([current, chunk]);
      if (next.length > MAX_OUTPUT_BYTES) {
        overflow = true;
        child.kill("SIGKILL");
      }
      return next.subarray(0, MAX_OUTPUT_BYTES);
    };
    child.stdout.on("data", (chunk) => {
      stdout = append(stdout, chunk);
    });
    child.stderr.on("data", (chunk) => {
      stderr = append(stderr, chunk);
    });
    const timer = setTimeout(() => {
      timedOut = true;
      child.kill("SIGKILL");
    }, timeoutMs);
    child.on("error", () => {
      clearTimeout(timer);
      finish({
        exitCode: null,
        signal: null,
        spawnError: true,
      });
    });
    child.on("close", (exitCode, signal) => {
      clearTimeout(timer);
      finish({
        exitCode,
        signal,
        spawnError: false,
      });
    });
  });
}

async function runCore(core) {
  const totalStarted = performance.now();
  const results = [];
  for (const entry of core) {
    const remaining =
      CORE_TOTAL_TIMEOUT_MS - (performance.now() - totalStarted);
    if (remaining <= 0) {
      throw new GovernanceError("RUNNER_TOTAL_TIMEOUT");
    }
    const before = repositoryStateDigest();
    const result = await runScript(
      entry.path,
      Math.min(PER_CHILD_TIMEOUT_MS, remaining),
      {
        preloads: [LEGACY_CORE_PRELOAD_URL],
        environment: CORE_SAFE_ENVIRONMENT,
      },
    );
    const after = repositoryStateDigest();
    const stdout = outputIdentity(result.stdout);
    const stderr = outputIdentity(result.stderr);
    const unchanged = before === after;
    const passed =
      result.exitCode === 0 &&
      result.signal === null &&
      result.stderr === "" &&
      !result.overflow &&
      !result.timedOut &&
      !result.spawnError &&
      unchanged;
    results.push({ path: entry.path, passed });
    console.log(
      "STATIC_CORE path=" +
        entry.path +
        " exit=" +
        (result.exitCode ?? "null") +
        " duration_ms=" +
        result.durationMs +
        " stdout_sha256=" +
        stdout.sha256 +
        " stdout_bytes=" +
        stdout.bytes +
        " stdout_lines=" +
        stdout.lines +
        " stderr_sha256=" +
        stderr.sha256 +
        " stderr_bytes=" +
        stderr.bytes +
        " stderr_lines=" +
        stderr.lines +
        " repository_state_unchanged=" +
        unchanged +
        " result=" +
        (passed ? "PASS" : "FAIL"),
    );
    if (!passed) {
      throw new GovernanceError("RUNNER_CORE_COMMAND_FAILED");
    }
  }
  console.log(
    "PASS_STATIC_READINESS_CORE commands=" +
      results.length +
      " pass=" +
      results.length +
      " fail=0 repository_mutations=0 total_duration_ms=" +
      Math.round(performance.now() - totalStarted),
  );
}

