function selfTestSnippet(category, body) {
  return [
    "try {",
    "  " + body,
    "  console.log(\"BYPASS_" + category + "\");",
    "  process.exitCode = 2;",
    "} catch (caught) {",
    "  if (caught && caught.code === \"STATIC_READINESS_SANDBOX_DENIED_" +
      category +
      "\") {",
    "    console.log(\"DENIED_" + category + "\");",
    "  } else {",
    "    console.log(\"WRONG_DENIAL_" + category + "\");",
    "    process.exitCode = 3;",
    "  }",
    "}",
    "",
  ].join("\n");
}

function replaceUniqueSourceFragment(source, fragment, replacement) {
  const first = source.indexOf(fragment);
  if (first < 0 || first !== source.lastIndexOf(fragment)) {
    throw new GovernanceError("RUNNER_C2_1_MUTATION_FIXTURE_IDENTITY");
  }
  return source.slice(0, first) + replacement + source.slice(first + fragment.length);
}

function expectC2SourcePolicyMutation(
  source,
  fragment,
  expectedStage,
  {
    family = "C2_1",
    expectedPaths = C2_1_ANALYZER_READ_PATHS,
    wrapperName = "readExactC2",
  } = {},
) {
  const mutated = replaceUniqueSourceFragment(source, fragment, "false");
  const sourceFile = ts.createSourceFile(
    family.toLowerCase().replace("_", "-") + "-source-policy-mutation.mjs",
    mutated,
    ts.ScriptTarget.Latest,
    true,
    ts.ScriptKind.JS,
  );
  try {
    validateReadExactC2Source(
      sourceFile,
      mutated,
      expectedPaths,
      { family, wrapperName },
    );
  } catch (caught) {
    if (caught instanceof GovernanceError && caught.stage === expectedStage) {
      return;
    }
    throw caught;
  }
  throw new GovernanceError("RUNNER_C2_1_MUTATION_NOT_REJECTED");
}

function validateC2SourcePolicyMutations() {
  const child = C2_1_CHILDREN[0];
  const source = readFileSync(child.path, "utf8");
  if (digest(Buffer.from(source, "utf8")) !== child.sha256) {
    throw new GovernanceError("RUNNER_C2_1_MUTATION_SOURCE_IDENTITY");
  }
  expectC2SourcePolicyMutation(
    source,
    "absolutePath === REPOSITORY_ROOT ||\n" +
      "    !absolutePath.startsWith(REPOSITORY_ROOT + path.sep)",
    "RUNNER_C2_1_READ_WRAPPER_ROOT_GUARD",
  );
  expectC2SourcePolicyMutation(
    source,
    "!metadata.isFile() || metadata.isSymbolicLink()",
    "RUNNER_C2_1_READ_WRAPPER_REGULAR_FILE_GUARD",
  );
}

function validateC2_2SourcePolicyMutations() {
  const child = C2_2_CHILDREN[0];
  const source = readFileSync(child.path, "utf8");
  if (digest(Buffer.from(source, "utf8")) !== child.sha256) {
    throw new GovernanceError("RUNNER_C2_2_MUTATION_SOURCE_IDENTITY");
  }
  const options = {
    family: "C2_2",
    expectedPaths: C2_2_ANALYZER_READ_PATHS,
    wrapperName: "readExactC2_2",
  };
  expectC2SourcePolicyMutation(
    source,
    "absolutePath === REPOSITORY_ROOT ||\n" +
      "    !absolutePath.startsWith(REPOSITORY_ROOT + path.sep)",
    "RUNNER_C2_2_READ_WRAPPER_ROOT_GUARD",
    options,
  );
  expectC2SourcePolicyMutation(
    source,
    "!metadata.isFile() || metadata.isSymbolicLink()",
    "RUNNER_C2_2_READ_WRAPPER_REGULAR_FILE_GUARD",
    options,
  );
}

async function runSelfTest() {
  if (
    !exactSet(
      V1_RUNTIME_CHILDREN.map((child) => child.path),
      EXPECTED_V1_RUNTIME_CHILD_PATHS,
    )
  ) {
    console.log(
      "EXPECTED_FAIL_STATIC_READINESS_RUNNER_SELF_TEST stage=V1_RUNTIME_POLICY_SET failures=1 internal_failures=0",
    );
    process.exitCode = 1;
    return;
  }
  if (
    !V1_RUNTIME_CHILDREN.every(
      (child) =>
        JSON.stringify(child.argv) ===
        JSON.stringify(EXPECTED_V1_RUNTIME_CHILD_ARGV.get(child.path)),
    )
  ) {
    console.log(
      "EXPECTED_FAIL_STATIC_READINESS_RUNNER_SELF_TEST stage=V1_RUNTIME_POLICY_ARGV failures=1 internal_failures=0",
    );
    process.exitCode = 1;
    return;
  }
  for (const child of V1_RUNTIME_CHILDREN) {
    validateV1RuntimeChildSource(child);
  }
  if (PHASE_COMPILER_CLOSURE_CONTRACTS.length !== 21) {
    console.log(
      "EXPECTED_FAIL_STATIC_READINESS_RUNNER_SELF_TEST stage=PHASE_COMPILER_CLOSURE_MISSING failures=1 internal_failures=0",
    );
    process.exitCode = 1;
    return;
  }
  const phaseCompilerClosureStarted = performance.now();
  const phaseCompilerClosure = validatePhaseCompilerClosure();
  validatePhaseCompilerClosureMutations();
  console.log(
    "SANDBOX_SELF_TEST family=PHASE_COMPILER_CLOSURE_POLICY duration_ms=" +
      Math.round(performance.now() - phaseCompilerClosureStarted) +
      " source_identities=" +
      phaseCompilerClosure.sourceIdentities +
      " import_allowlists=" +
      phaseCompilerClosure.importAllowlists +
      " capability_profiles=" +
      phaseCompilerClosure.capabilityProfiles +
      " result=PASS",
  );
  if (
    !exactSet(
      PHASE_COMPILER_CHILDREN.map((child) => child.path),
      EXPECTED_PHASE_COMPILER_CHILD_PATHS,
    )
  ) {
    console.log(
      "EXPECTED_FAIL_STATIC_READINESS_RUNNER_SELF_TEST stage=PHASE_COMPILER_POLICY_SET failures=1 internal_failures=0",
    );
    process.exitCode = 1;
    return;
  }
  for (const child of PHASE_COMPILER_CHILDREN) {
    validatePhaseCompilerChildSource(child);
  }
  if (
    !exactSet(
      V1_STAGING_CHILDREN.map((child) => child.path),
      EXPECTED_V1_STAGING_CHILD_PATHS,
    )
  ) {
    console.log(
      "EXPECTED_FAIL_STATIC_READINESS_RUNNER_SELF_TEST stage=V1_STAGING_POLICY_SET failures=1 internal_failures=0",
    );
    process.exitCode = 1;
    return;
  }
  for (const child of V1_STAGING_CHILDREN) {
    validateV1StagingChildSource(child);
  }
  if (
    !exactSet(
      V1_ADMIN_CHILDREN.map((child) => child.path),
      EXPECTED_V1_ADMIN_CHILD_PATHS,
    )
  ) {
    console.log(
      "EXPECTED_FAIL_STATIC_READINESS_RUNNER_SELF_TEST stage=RUNNER_V1_ADMIN_POLICY_SET failures=1 internal_failures=0",
    );
    process.exitCode = 1;
    return;
  }
  for (const child of V1_ADMIN_CHILDREN) {
    validateV1AdminChildSource(child);
  }
  if (
    !exactSet(
      C2_2_CHILDREN.map((child) => child.path),
      EXPECTED_C2_2_CHILD_PATHS,
    )
  ) {
    console.log(
      "EXPECTED_FAIL_STATIC_READINESS_RUNNER_SELF_TEST stage=RUNNER_C2_2_POLICY_SET failures=1 internal_failures=0",
    );
    process.exitCode = 1;
    return;
  }
  if (
    !exactSet(
      C2_1_CHILDREN.map((child) => child.path),
      EXPECTED_C2_1_CHILD_PATHS,
    )
  ) {
    console.log(
      "EXPECTED_FAIL_STATIC_READINESS_RUNNER_SELF_TEST stage=RUNNER_C2_1_POLICY_SET failures=1 internal_failures=0",
    );
    process.exitCode = 1;
    return;
  }
  validateC2SourcePolicyMutations();
  const c2_2SourcePolicyStarted = performance.now();
  validateC2_2SourcePolicyMutations();
  const temporaryDirectory = mkdtempSync(
    path.join(os.tmpdir(), "aifinder-static-readiness-"),
  );
  const fixtures = [
    ["GLOBAL_NETWORK", "await fetch('http://127.0.0.1/');"],
    [
      "MODULE_NETWORK",
      "const http = await import('node:http'); http.get('http://127.0.0.1/');",
    ],
    [
      "CHILD_PROCESS",
      "const cp = await import('node:child_process'); cp.execFileSync('true');",
    ],
    [
      "FILESYSTEM_MUTATION",
      "const fs = await import('node:fs'); fs.writeFileSync(new URL('./blocked.txt', import.meta.url), 'blocked');",
    ],
  ];
  try {
    const results = [
      { category: "PHASE_COMPILER_CLOSURE_POLICY", passed: true },
      { category: "C2_2_SOURCE_POLICY", passed: true },
    ];
    console.log(
      "SANDBOX_SELF_TEST family=C2_2_SOURCE_POLICY duration_ms=" +
        Math.round(performance.now() - c2_2SourcePolicyStarted) +
        " result=PASS",
    );
    for (const [category, body] of fixtures) {
      const fixture = path.join(
        temporaryDirectory,
        category.toLowerCase() + ".mjs",
      );
      writeFileSync(fixture, selfTestSnippet(category, body), { mode: 0o600 });
      const result = await runScript(fixture, 5_000, {
        preloads: [SANDBOX_PATH],
        environment: CORE_SAFE_ENVIRONMENT,
        cwd: temporaryDirectory,
      });
      const passed =
        result.exitCode === 0 &&
        result.signal === null &&
        result.stdout === "DENIED_" + category + "\n" &&
        result.stderr === "" &&
        !result.overflow &&
        !result.timedOut &&
        !result.spawnError;
      results.push({ category, passed });
      console.log(
        "SANDBOX_SELF_TEST family=" +
          category +
          " duration_ms=" +
          result.durationMs +
          " result=" +
          (passed ? "PASS" : "FAIL"),
      );
    }
    if (!results.every((result) => result.passed)) {
      throw new GovernanceError("SANDBOX_SELF_TEST_FAILED");
    }
    console.log(
      "PASS_STATIC_READINESS_SANDBOX_SELF_TEST families=" +
        results.length +
        " pass=" +
        results.length +
        " fail=0",
    );
  } finally {
    rmSync(temporaryDirectory, { recursive: true, force: true });
  }
}

