try {
  const argumentsList = process.argv.slice(2);
  if (argumentsList.length > 1) {
    throw new GovernanceError("RUNNER_ARGUMENT");
  }
  const option = argumentsList[0] ?? "";
  if (option === "--self-test") {
    await runSelfTest();
  } else if (option === "--list") {
    const {
      core,
      c1Policy,
      c2Policy,
      c2_2Policy,
      v1AdminPolicy,
      v1StagingPolicy,
      phaseCompilerPolicy,
      v1RuntimePolicy,
    } = validateManifestForExecution();
    listChildren(
      core,
      c1Policy,
      c2Policy,
      c2_2Policy,
      v1AdminPolicy,
      v1StagingPolicy,
      phaseCompilerPolicy,
      v1RuntimePolicy,
    );
  } else if (option === "--c1-policy") {
    const { c1Policy } = validateManifestForExecution();
    await runC1Policy(c1Policy);
  } else if (option === "--c2-1-policy") {
    const { c2Policy } = validateManifestForExecution();
    await runC2Policy(c2Policy);
  } else if (option === "--c2-2-policy") {
    const { c2_2Policy } = validateManifestForExecution();
    await runC2_2Policy(c2_2Policy);
  } else if (option === "--v1-admin-policy") {
    const { v1AdminPolicy } = validateManifestForExecution();
    await runV1AdminPolicy(v1AdminPolicy);
  } else if (option === "--v1-staging-policy") {
    const { v1StagingPolicy } = validateManifestForExecution();
    await runV1StagingPolicy(v1StagingPolicy);
  } else if (option === "--phase-compiler-policy") {
    const { phaseCompilerPolicy } = validateManifestForExecution();
    await runPhaseCompilerPolicy(phaseCompilerPolicy);
  } else if (option === "--v1-runtime-policy") {
    const { v1RuntimePolicy } = validateManifestForExecution();
    await runV1RuntimePolicy(v1RuntimePolicy);
  } else if (option === "") {
    const {
      core,
      c1Policy,
      c2Policy,
      c2_2Policy,
      v1AdminPolicy,
      v1StagingPolicy,
      phaseCompilerPolicy,
      v1RuntimePolicy,
    } = validateManifestForExecution();
    await runCore(core);
    await runC1Policy(c1Policy);
    await runC2Policy(c2Policy);
    console.log(
      "PASS_STATIC_READINESS_C2_1_COMPLETE core=5 c1=4 c2_1=2 fail=0 repository_mutations=0",
    );
    await runC2_2Policy(c2_2Policy);
    console.log(
      "PASS_STATIC_READINESS_C2_2_COMPLETE core=5 c1=4 c2_1=2 c2_2=2 fail=0 repository_mutations=0",
    );
    await runV1AdminPolicy(v1AdminPolicy);
    console.log(
      "PASS_STATIC_READINESS_V1_ADMIN_COMPLETE core=5 c1=4 c2_1=2 c2_2=2 v1_admin=2 fail=0 repository_mutations=0",
    );
    await runV1StagingPolicy(v1StagingPolicy);
    console.log(
      "PASS_STATIC_READINESS_V1_STAGING_COMPLETE core=5 c1=4 c2_1=2 c2_2=2 v1_admin=2 v1_staging=2 fail=0 repository_mutations=0",
    );
    await runPhaseCompilerPolicy(phaseCompilerPolicy);
    console.log(
      "PASS_STATIC_READINESS_PHASE_COMPILER_COMPLETE core=5 c1=4 c2_1=2 c2_2=2 v1_admin=2 v1_staging=2 phase_compiler=3 total=20 fail=0 repository_mutations=0 source_identities=21 import_allowlists=17 capability_profiles=21 compiled_phase_commands_executed=0",
    );
    await runV1RuntimePolicy(v1RuntimePolicy);
    console.log(
      "PASS_STATIC_READINESS_V1_RUNTIME_COMPLETE core=5 c1=4 c2_1=2 c2_2=2 v1_admin=2 v1_staging=2 phase_compiler=3 v1_runtime=2 total=22 fail=0 repository_mutations=0 live_orchestrator_executed=0",
    );
    console.log(
      "PASS_STATIC_READINESS_COMPLETE core=5 c1=4 fail=0 repository_mutations=0",
    );
  } else {
    throw new GovernanceError("RUNNER_ARGUMENT");
  }
} catch (caught) {
  const stage =
    caught instanceof GovernanceError
      ? caught.stage
      : "INTERNAL_RUNNER_FAILURE";
  console.log("FAIL_STATIC_READINESS_RUNNER stage=" + stage);
  process.exitCode = 1;
}
